"""Application configuration sourced from environment variables and CLI flags."""

from __future__ import annotations

import os
import re
from dataclasses import dataclass
from pathlib import Path


_COLLECTION_NAME = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{1,509}[A-Za-z0-9]$")


def _env_int(name: str, default: int) -> int:
    raw = os.getenv(name)
    if raw is None:
        return default
    try:
        return int(raw)
    except ValueError as exc:
        raise ValueError(f"{name} must be an integer, got {raw!r}") from exc


@dataclass(frozen=True)
class Settings:
    """Validated settings needed by document ingestion."""

    chroma_path: Path
    collection_name: str
    embedding_model: str
    chunk_size: int
    chunk_overlap: int
    embedding_batch_size: int

    @classmethod
    def from_env(cls) -> "Settings":
        settings = cls(
            chroma_path=Path(os.getenv("RAG_CHROMA_PATH", ".chroma")),
            collection_name=os.getenv("RAG_COLLECTION_NAME", "rag-documents"),
            embedding_model=os.getenv(
                "RAG_EMBEDDING_MODEL",
                "sentence-transformers/all-MiniLM-L6-v2",
            ),
            chunk_size=_env_int("RAG_CHUNK_SIZE", 800),
            chunk_overlap=_env_int("RAG_CHUNK_OVERLAP", 120),
            embedding_batch_size=_env_int("RAG_EMBEDDING_BATCH_SIZE", 32),
        )
        settings.validate()
        return settings

    def validate(self) -> None:
        if self.chunk_size < 100:
            raise ValueError("chunk_size must be at least 100 characters")
        if self.chunk_overlap < 0:
            raise ValueError("chunk_overlap cannot be negative")
        if self.chunk_overlap >= self.chunk_size:
            raise ValueError("chunk_overlap must be smaller than chunk_size")
        if self.embedding_batch_size < 1:
            raise ValueError("embedding_batch_size must be at least 1")
        if not _COLLECTION_NAME.fullmatch(self.collection_name):
            raise ValueError(
                "collection_name must be 3-512 characters, start and end with "
                "an alphanumeric character, and contain only letters, numbers, "."
                "periods, underscores, or hyphens"
            )

"""Runtime document discovery and text extraction."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Iterable

from rag_generator.ingestion.models import LoadedDocument


SUPPORTED_EXTENSIONS = frozenset({".txt", ".md", ".pdf"})


class IngestionInputError(ValueError):
    """Raised when the requested source cannot be ingested."""


class DocumentLoadError(RuntimeError):
    """Raised when a supported document cannot be read safely."""


@dataclass(frozen=True)
class LoadResult:
    documents: tuple[LoadedDocument, ...]
    loaded_files: tuple[str, ...]
    skipped_files: tuple[str, ...]
    warnings: tuple[str, ...]


def discover_files(source: Path) -> list[Path]:
    """Return deterministic file paths from a single file or directory."""

    source = source.expanduser()
    if not source.exists():
        raise IngestionInputError(f"Document path does not exist: {source}")
    if source.is_file():
        return [source]
    if not source.is_dir():
        raise IngestionInputError(f"Document path is not a file or directory: {source}")
    return sorted(
        (path for path in source.rglob("*") if path.is_file()),
        key=lambda path: path.as_posix().casefold(),
    )


def load_documents(source: Path) -> LoadResult:
    """Load all supported files while retaining citation metadata."""

    source = source.expanduser().resolve()
    files = discover_files(source)
    if not files:
        raise IngestionInputError(f"No files found in: {source}")

    documents: list[LoadedDocument] = []
    loaded_files: list[str] = []
    skipped_files: list[str] = []
    warnings: list[str] = []

    for path in files:
        relative_name = _relative_source(path, source)
        suffix = path.suffix.lower()
        if suffix not in SUPPORTED_EXTENSIONS:
            skipped_files.append(relative_name)
            warnings.append(f"Skipped unsupported file: {relative_name}")
            continue

        extracted = _load_file(path, relative_name, suffix)
        if not extracted:
            skipped_files.append(relative_name)
            warnings.append(f"Skipped file with no extractable text: {relative_name}")
            continue

        documents.extend(extracted)
        loaded_files.append(relative_name)

    if not documents:
        supported = ", ".join(sorted(SUPPORTED_EXTENSIONS))
        raise IngestionInputError(
            f"No readable documents found in {source}. Supported extensions: {supported}"
        )

    return LoadResult(
        documents=tuple(documents),
        loaded_files=tuple(loaded_files),
        skipped_files=tuple(skipped_files),
        warnings=tuple(warnings),
    )


def _relative_source(path: Path, source: Path) -> str:
    if source.is_file():
        return source.name
    return path.relative_to(source).as_posix()


def _load_file(path: Path, source_name: str, suffix: str) -> Iterable[LoadedDocument]:
    if suffix in {".txt", ".md"}:
        return _load_text(path, source_name, suffix)
    if suffix == ".pdf":
        return _load_pdf(path, source_name)
    return ()


def _load_text(path: Path, source_name: str, suffix: str) -> tuple[LoadedDocument, ...]:
    try:
        text = path.read_text(encoding="utf-8-sig")
    except (OSError, UnicodeError) as exc:
        raise DocumentLoadError(f"Could not read {source_name}: {exc}") from exc

    if not text.strip():
        return ()
    return (LoadedDocument(source_name, text, suffix.removeprefix(".")),)


def _load_pdf(path: Path, source_name: str) -> tuple[LoadedDocument, ...]:
    try:
        from pypdf import PdfReader
    except ImportError as exc:  # pragma: no cover - depends on environment
        raise DocumentLoadError(
            "PDF support requires pypdf. Install project dependencies first."
        ) from exc

    try:
        reader = PdfReader(path)
        pages = []
        for page_number, page in enumerate(reader.pages, start=1):
            text = page.extract_text() or ""
            if text.strip():
                pages.append(
                    LoadedDocument(
                        source=source_name,
                        text=text,
                        file_type="pdf",
                        page=page_number,
                    )
                )
        return tuple(pages)
    except Exception as exc:
        raise DocumentLoadError(f"Could not extract text from {source_name}: {exc}") from exc

"""Structure-aware text chunking with deterministic citation metadata."""

from __future__ import annotations

import hashlib
import re
from dataclasses import dataclass
from typing import Iterable

from rag_generator.ingestion.models import LoadedDocument, TextChunk


_BOUNDARY_PATTERNS = (
    re.compile(r"\n(?=#{1,6}\s)"),
    re.compile(r"\n\s*\n"),
    re.compile(r"(?<=[.!?])\s+"),
    re.compile(r"\n"),
    re.compile(r"\s+"),
)


@dataclass(frozen=True)
class TextChunker:
    chunk_size: int = 800
    chunk_overlap: int = 120

    def __post_init__(self) -> None:
        if self.chunk_size < 100:
            raise ValueError("chunk_size must be at least 100 characters")
        if self.chunk_overlap < 0 or self.chunk_overlap >= self.chunk_size:
            raise ValueError("chunk_overlap must be non-negative and smaller than chunk_size")

    def chunk_documents(self, documents: Iterable[LoadedDocument]) -> list[TextChunk]:
        chunks: list[TextChunk] = []
        per_source_index: dict[tuple[str, int | None], int] = {}

        for document in documents:
            key = (document.source, document.page)
            next_index = per_source_index.get(key, 0)
            for start, end, text in self._windows(document.text):
                chunk_id = _chunk_id(document, next_index, text)
                chunks.append(
                    TextChunk(
                        id=chunk_id,
                        text=text,
                        source=document.source,
                        file_type=document.file_type,
                        page=document.page,
                        chunk_index=next_index,
                        char_start=start,
                        char_end=end,
                    )
                )
                next_index += 1
            per_source_index[key] = next_index
        return chunks

    def _windows(self, text: str) -> Iterable[tuple[int, int, str]]:
        start = 0
        text_length = len(text)

        while start < text_length:
            target_end = min(start + self.chunk_size, text_length)
            end = target_end
            if target_end < text_length:
                minimum_end = start + max(self.chunk_size // 2, 1)
                end = _preferred_end(text, minimum_end, target_end)

            raw = text[start:end]
            left_trim = len(raw) - len(raw.lstrip())
            right_trim = len(raw.rstrip())
            clean = raw.strip()
            if clean:
                yield start + left_trim, start + right_trim, clean

            if end >= text_length:
                break

            proposed_start = max(0, end - self.chunk_overlap)
            next_start = _word_boundary_at_or_before(text, proposed_start, end)
            if next_start <= start:
                next_start = end
            start = next_start


def _preferred_end(text: str, minimum: int, maximum: int) -> int:
    window = text[minimum:maximum]
    for pattern in _BOUNDARY_PATTERNS:
        matches = list(pattern.finditer(window))
        if matches:
            return minimum + matches[-1].start()
    return maximum


def _word_boundary_at_or_before(text: str, target: int, maximum: int) -> int:
    if target <= 0:
        return 0
    for position in range(target, max(target - 40, 0), -1):
        if text[position - 1].isspace():
            return position
    for position in range(target, min(target + 40, maximum)):
        if text[position].isspace():
            return position + 1
    return target


def _chunk_id(document: LoadedDocument, index: int, text: str) -> str:
    identity = f"{document.source}\0{document.page or 0}\0{index}\0{text}"
    digest = hashlib.sha256(identity.encode("utf-8")).hexdigest()[:20]
    return f"chunk-{digest}"

"""Sentence Transformers embedding adapter."""

from __future__ import annotations

from collections.abc import Sequence
from typing import Any


class EmbeddingError(RuntimeError):
    """Raised when the local embedding model cannot produce vectors."""


class MiniLMEmbedder:
    def __init__(self, model_name: str, batch_size: int = 32) -> None:
        self.model_name = model_name
        self.batch_size = batch_size
        self._model: Any | None = None

    def embed_documents(self, texts: Sequence[str]) -> list[list[float]]:
        if not texts:
            return []
        try:
            model = self._get_model()
            vectors = model.encode(
                list(texts),
                batch_size=self.batch_size,
                show_progress_bar=len(texts) > self.batch_size,
                convert_to_numpy=True,
                normalize_embeddings=True,
            )
            return vectors.tolist()
        except EmbeddingError:
            raise
        except Exception as exc:
            raise EmbeddingError(f"Embedding failed: {exc}") from exc

    def _get_model(self) -> Any:
        if self._model is not None:
            return self._model
        try:
            from sentence_transformers import SentenceTransformer
        except ImportError as exc:  # pragma: no cover - depends on environment
            raise EmbeddingError(
                "Embedding support requires sentence-transformers. "
                "Install project dependencies first."
            ) from exc
        try:
            self._model = SentenceTransformer(self.model_name)
        except Exception as exc:
            raise EmbeddingError(
                f"Could not load embedding model {self.model_name!r}: {exc}"
            ) from exc
        return self._model

